{
  "verdict": "revise",
  "reason": "El diseño aborda con precisión la causa raíz del déficit informativo al eliminar la asimetría de especificación del put y la opacidad de ControllerError('invalid author manifest'), sin relajar las 9 fases ni tolerar aprobaciones o pruebas sintéticas. La preservación de validación estricta y el salto a schema 10 protegen la inmutabilidad de la evidencia histórica (schema 9). No obstante, requiere revisión en tres puntos críticos de diseño antes de implementación: sanitización estructural de diagnósticos (evitar que excepciones estándar interpolen tokens arbitrarios del autor), garantía de paridad simétrica de contrato entre ramas T y A para no introducir sesgos informacionales espurios, y un mecanismo de build-time check que prevenga desincronizaciones entre el validador Python _manifest_steps y el artefacto JSON.",
  "findings": [
    {
      "problem": "Riesgo de fuga o inyección de contenido no confiable al propagar la excepción de bajo nivel si el validador o parser de Python interpola claves o valores del payload en el mensaje de error.",
      "correction": "Tipificar los diagnósticos mediante códigos de error canónicos cerrados (ej. ERR_MISSING_OP, ERR_EMPTY_STEPS, ERR_INVALID_ITEM_ID, ERR_DEPS_TYPE_MISMATCH) en lugar de propagar cadenas de excepción sin sanitizar."
    },
    {
      "problem": "Posible asimetría metodológica si el contrato estructurado se entrega solo al Tratamiento (T) o de forma diferenciada frente a la Ablación (A), confundiendo la evaluación de la metodología con el acceso a la sintaxis del esquema.",
      "correction": "Exponer el archivo de contrato autor-manifest-contract.json de manera idéntica y canónica en el contexto de entrada tanto para T como para A, diferenciando las condiciones experimentales únicamente por sus directrices metodológicas operativas."
    },
    {
      "problem": "Riesgo de deriva (drift) entre el contrato estático autor-manifest-contract.json y la lógica de validación en _manifest_steps.",
      "correction": "Derivar programáticamente el contrato JSON directamente desde las constantes y firmas de _manifest_steps / engine.ITEM_ID mediante un generador determinista validado en CI."
    }
  ],
  "contract_specification": {
    "required_content": [
      "schema: integer fijo en 1",
      "steps: array no vacío de objetos 'put', incluso en fase build",
      "campos requeridos por put: op ('put'), id (regex engine.ITEM_ID), kind, text, refs (lista de IDs válidos), data (objeto)",
      "campos opcionales por put: expected_version (int >= 0), expected_deps (map string->int >= 1)",
      "campos y valores prohibidos: op 'advance', passed, receipt, test_job_ref, y campos extra no declarados",
      "especificación explícita de ruta N/S: steps=[] exclusivo para ejecuciones sin autor/baseline, inválido en autoría activa"
    ],
    "identified_risks": [
      "Sobrecarga de tokens de contexto que desplace espacio de razonamiento substantivo",
      "Desincronización silenciosa entre esquema publicado y parser en tiempo de ejecución",
      "Interpolación accidental de texto no sanitizado en telemetría de fallos",
      "Sesgo comparativo si no se calibra la entrega del esquema en todas las ramas"
    ]
  },
  "proposed_tests": [
    {
      "name": "test_author_manifest_contract_schema_parity",
      "objective": "Verificar en CI que autor-manifest-contract.json y el validador runtime _manifest_steps utilicen la misma expresión regular engine.ITEM_ID y el mismo conjunto de campos requeridos/prohibidos sin desincronización."
    },
    {
      "name": "test_diagnostic_sanitization_no_content_leak",
      "objective": "Comprobar que ante payloads malformados (claves extra, inyección de scripts/texto arbitrario, tipos erróneos) el diagnóstico retorne códigos cerrados canónicos sin reflejar cadenas del autor en la telemetría."
    },
    {
      "name": "test_strict_rejection_of_empty_steps_and_synthetic_evidence",
      "objective": "Confirmar que build con steps=[] sea rechazado categóricamente, y que intentos de inyectar op 'advance', test_job_ref, passed o receipt generen ControllerError estricto sin coerción ni auto-completado."
    }
  ],
  "tests_executed": false
}
